import java.awt.*;public class PrimeDriver extends Frame{    private String primes = new String();	public PrimeDriver(){		TextArea text = new TextArea("", 10,10);     	text.setEditable( false ); 		add(text);			calculatePrime();		text.setText(primes);	}	public void calculatePrime(){		 	int[] prime = new int[10000];        prime[0]=3;        int test=5, index=0;        int num=0;        boolean check=true;        primes = (prime[0] +"\r\n");	        while(test<10000)        {                       index=0;                 check=true;                while(check==true && index<=num && test>=(prime[index]*prime[index]))                {                      	 	if(test%prime[index] == 0)                  		check=false;                 	else                  		index++;                }                if(check==true)                {                	primes+= test +"\r\n";                	if(num<(prime.length-1)){                       		num++;                        prime[num]=test;                    }                 }                test+=2;        }	}	public String toString(){		return primes;	}	public static void main(String[] args){			PrimeDriver driver = new PrimeDriver();		driver.show();	}	}